import React from "react";
import { useLocation, Link } from "react-router-dom";
import "./global.css";

export default function ThankYouPage() {
  const { state } = useLocation();
  const product = state?.product;
  const method = state?.method;

  return (
    <div className="thankyou-container">
      <h1>🎉 Thank You!</h1>

      {product && (
        <p className="thankyou-details">
          {method === "Swap Request Sent" ? (
            <>
              Your <strong>swap request</strong> for
              <strong> {product.title}</strong> was sent successfully!
            </>
          ) : (
            <>
              Your purchase of
              <strong> {product.title}</strong> using
              <strong> {method}</strong> was successful!
            </>
          )}
        </p>
      )}

      <Link to="/" className="back-home-btn">
        Go Back Home
      </Link>
    </div>
  );
}
